input.sparql:
PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?zone ?zoneName ?tsid WHERE {
  ?zone a brick:Zone ;
        brick:hasPoint ?pt .
  a_kind ?pt rdf:type .
  ?pt ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?tsid .
}
LIMIT 200

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?zone ?zoneLabel ?pt ?ptLabel ?tsid WHERE {
  ?zone a brick:Zone .
  OPTIONAL { ?zone rdfs:label ?zoneLabel }
  ?zone brick:hasPoint ?pt .
  ?pt ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?tsid .
}
LIMIT 200

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?s ?p ?o WHERE {
  ?s brick:hasPoint ?o .
}
LIMIT 200

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT DISTINCT ?t WHERE {
  ?s a ?t .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?zone ?zoneLabel ?pt ?ptT ?tsid
WHERE {
  ?zone a brick:HVAC_Zone .
  OPTIONAL { ?zone rdfs:label ?zoneLabel }
  OPTIONAL { ?zone brick:hasPoint ?pt }
  OPTIONAL { ?pt rdf:type ?ptT }
  OPTIONAL { ?pt ref:hasExternalReference ?ref ; ref:hasTimeseriesId ?tsid }
}

